import { useMemo, useState } from "react";
import { useLocation } from "wouter";
import DashboardLayout from "@/components/DashboardLayout";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { ArrowDownRight, ArrowUpRight, BarChart3, BookOpen, Calculator, CircleDollarSign, FilePlus2, Landmark, Loader2, RefreshCw, ShieldAlert, Target, UserPlus, WalletCards } from "lucide-react";
import { toast } from "sonner";
import { trpc } from "@/lib/trpc";
import { processamento_validateCnpj } from "../../../shared/finance";
import { jsPDF } from "jspdf";
import { Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

const money = (value: number | string | null | undefined) => Number(value ?? 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const pct = (value: number | null | undefined) => value === null || value === undefined ? "—" : `${value.toFixed(1)}%`;
const csvCell = (value: unknown) => `"${String(value ?? "").replaceAll("\"", "\"\"")}"`;
function downloadCsv(filename: string, headers: string[], rows: unknown[][]) { const content = [headers, ...rows].map(row => row.map(csvCell).join(";")).join("\n"); const blob = new Blob(["\ufeff" + content], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url); }
function exportPdf(filename: string, title: string, subtitle: string, headers: string[], rows: unknown[][]) { const doc = new jsPDF({ orientation: headers.length > 5 ? "landscape" : "portrait" }); let y = 18; doc.setFontSize(16); doc.text(title, 14, y); y += 8; doc.setFontSize(9); doc.setTextColor(90); doc.text(subtitle, 14, y); y += 10; doc.setTextColor(30); doc.setFontSize(8); const widths = headers.map(() => (doc.internal.pageSize.getWidth() - 28) / headers.length); const drawRow = (values: unknown[], bold = false) => { if (y > doc.internal.pageSize.getHeight() - 15) { doc.addPage(); y = 15; } doc.setFont("helvetica", bold ? "bold" : "normal"); values.forEach((value, index) => doc.text(String(value ?? "").slice(0, 28), 14 + widths.slice(0, index).reduce((sum, width) => sum + width, 0), y)); y += 6; }; drawRow(headers, true); doc.setDrawColor(210); doc.line(14, y - 3, doc.internal.pageSize.getWidth() - 14, y - 3); rows.forEach(row => drawRow(row)); doc.save(filename); }
const currentMonth = new Date().toISOString().slice(0, 7);
const isoToday = new Date().toISOString().slice(0, 10);

function KpiCard({ title, value, helper, icon: Icon, tone = "blue" }: { title: string; value: string; helper: string; icon: typeof WalletCards; tone?: "blue" | "emerald" | "amber" | "rose" }) {
  const tones = { blue: "bg-blue-500/10 text-blue-600", emerald: "bg-emerald-500/10 text-emerald-600", amber: "bg-amber-500/10 text-amber-600", rose: "bg-rose-500/10 text-rose-600" };
  return <Card className="border-border/70 shadow-sm"><CardContent className="p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-medium uppercase tracking-[0.14em] text-muted-foreground">{title}</p><p className="mt-2 text-2xl font-semibold tracking-tight">{value}</p><p className="mt-1 text-xs text-muted-foreground">{helper}</p></div><div className={`rounded-xl p-2.5 ${tones[tone]}`}><Icon className="h-5 w-5" /></div></div></CardContent></Card>;
}

function EmptyState({ title, detail }: { title: string; detail: string }) {
  return <div className="rounded-xl border border-dashed border-border bg-muted/20 px-6 py-10 text-center"><BookOpen className="mx-auto h-8 w-8 text-muted-foreground/60" /><p className="mt-3 font-medium">{title}</p><p className="mx-auto mt-1 max-w-md text-sm text-muted-foreground">{detail}</p></div>;
}

function LaunchForm({ catalog, operations, onDone }: { catalog: { products: any[]; providers: any[]; costCenters: any[] }; operations: { customers?: any[]; contracts?: any[] }; onDone: () => void }) {
  const create = trpc.finance.createTransaction.useMutation({ onSuccess: () => { toast.success("Lançamento registrado"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ type: "income" as "income" | "expense", productId: "", customerId: "", contractId: "", providerId: "", costCenterId: "", category: "Mensalidade", description: "", amount: "", occurredAt: isoToday, notes: "" });
  const productOptions = catalog.products;
  const costCenters = catalog.costCenters.filter(center => form.type === "expense" ? center.kind === "cogs" || center.kind === "opex" : center.kind === "revenue");
  const update = (key: string, value: string) => setForm(prev => ({ ...prev, [key]: value }));
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!form.description || !form.amount || !form.costCenterId) { toast.error("Preencha descrição, valor e centro de custo"); return; } create.mutate({ type: form.type, category: form.category, description: form.description, amount: Number(form.amount), occurredAt: new Date(`${form.occurredAt}T12:00:00.000Z`).toISOString(), competenceMonth: form.occurredAt.slice(0, 7), productId: form.productId ? Number(form.productId) : undefined, customerId: form.customerId ? Number(form.customerId) : undefined, contractId: form.contractId ? Number(form.contractId) : undefined, providerId: form.providerId ? Number(form.providerId) : undefined, costCenterId: Number(form.costCenterId), notes: form.notes || undefined }); };
  return <form onSubmit={submit} className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Tipo de lançamento</Label><Select value={form.type} onValueChange={value => { update("type", value); setForm(prev => ({ ...prev, type: value as "income" | "expense", costCenterId: "" })); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="income">Entrada recebida</SelectItem><SelectItem value="expense">Saída / despesa</SelectItem></SelectContent></Select></div><div className="space-y-2"><Label>Valor recebido ou pago</Label><Input type="number" min="0.01" step="0.01" value={form.amount} onChange={e => update("amount", e.target.value)} placeholder="0,00" /></div><div className="space-y-2"><Label>Produto SaaS</Label><Select value={form.productId || "group"} onValueChange={value => update("productId", value === "group" ? "" : value)}><SelectTrigger><SelectValue placeholder="Grupo Elo / produto" /></SelectTrigger><SelectContent><SelectItem value="group">Grupo Elo — consolidado</SelectItem>{productOptions.map(product => <SelectItem key={product.id} value={String(product.id)}>{product.name}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Cliente</Label><Select value={form.customerId || "none"} onValueChange={value => update("customerId", value === "none" ? "" : value)}><SelectTrigger><SelectValue placeholder="Não vinculado" /></SelectTrigger><SelectContent><SelectItem value="none">Não vinculado</SelectItem>{(operations.customers ?? []).map(customer => <SelectItem key={customer.id} value={String(customer.id)}>{customer.legalName}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Contrato / mensalidade</Label><Select value={form.contractId || "none"} onValueChange={value => update("contractId", value === "none" ? "" : value)}><SelectTrigger><SelectValue placeholder="Não vinculado" /></SelectTrigger><SelectContent><SelectItem value="none">Não vinculado</SelectItem>{(operations.contracts ?? []).map(contract => <SelectItem key={contract.id} value={String(contract.id)}>{contract.code}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Centro de custo</Label><Select value={form.costCenterId} onValueChange={value => update("costCenterId", value)}><SelectTrigger><SelectValue placeholder="Selecione a classificação" /></SelectTrigger><SelectContent>{costCenters.map(center => <SelectItem key={center.id} value={String(center.id)}>{center.name}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Provedor de infraestrutura (se aplicável)</Label><Select value={form.providerId || "none"} onValueChange={value => update("providerId", value === "none" ? "" : value)}><SelectTrigger><SelectValue placeholder="Não se aplica" /></SelectTrigger><SelectContent><SelectItem value="none">Não se aplica</SelectItem>{catalog.providers.map(provider => <SelectItem key={provider.id} value={String(provider.id)}>{provider.name}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Data do lançamento</Label><Input type="date" value={form.occurredAt} onChange={e => update("occurredAt", e.target.value)} /></div><div className="space-y-2 md:col-span-2"><Label>Categoria</Label><Input value={form.category} onChange={e => update("category", e.target.value)} placeholder="Ex.: mensalidade, GCP, folha, marketing" /></div><div className="space-y-2 md:col-span-2"><Label>Descrição</Label><Input value={form.description} onChange={e => update("description", e.target.value)} placeholder="Descreva o fato financeiro" /></div><div className="space-y-2 md:col-span-2"><Label>Observações</Label><Input value={form.notes} onChange={e => update("notes", e.target.value)} placeholder="Opcional" /></div><div className="md:col-span-2 flex justify-end"><Button disabled={create.isPending} type="submit">{create.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <FilePlus2 className="mr-2 h-4 w-4" />}Registrar lançamento</Button></div></form>;
}

function HomeContent() {
  const [location] = useLocation();
  const [month, setMonth] = useState(currentMonth);
  const [productId, setProductId] = useState<string>("group");
  const [showLaunch, setShowLaunch] = useState(location === "/lancamentos");
  const [historyType, setHistoryType] = useState<"all" | "income" | "expense">("all");
  const [dreMode, setDreMode] = useState<"month" | "quarter" | "year">("month");
  const [historyCategory, setHistoryCategory] = useState("");
  const [historyProvider, setHistoryProvider] = useState("all");
  const [invoiceSearch, setInvoiceSearch] = useState("");
  const [invoiceStatus, setInvoiceStatus] = useState<"all" | "confirmed" | "pending" | "cancelled">("all");
  const [invoiceFrom, setInvoiceFrom] = useState("");
  const [invoiceTo, setInvoiceTo] = useState("");
  const [goalYear, setGoalYear] = useState(new Date().getFullYear());
  const catalogQuery = trpc.finance.catalog.useQuery();
  const operationsQuery = trpc.finance.operations.useQuery();
  const catalog = catalogQuery.data ?? { products: [], providers: [], costCenters: [] };
  const selectedProductId = productId === "group" ? undefined : Number(productId);
  const dashboardInput = useMemo(() => ({ month, ...(selectedProductId ? { productId: selectedProductId } : {}) }), [month, selectedProductId]);
  const transactionInput = useMemo(() => ({ month, ...(selectedProductId ? { productId: selectedProductId } : {}), ...(historyType !== "all" ? { type: historyType } : {}), ...(historyCategory ? { category: historyCategory } : {}), ...(historyProvider !== "all" ? { providerId: Number(historyProvider) } : {}) }), [month, selectedProductId, historyType, historyCategory, historyProvider]);
  const dashboard = trpc.finance.dashboard.useQuery(dashboardInput);
  const transactions = trpc.finance.transactions.useQuery(transactionInput);
  const goals = trpc.finance.goals.useQuery({ year: goalYear, ...(selectedProductId ? { productId: selectedProductId } : {}) });
  const utils = trpc.useUtils();
  const refresh = () => { void utils.finance.dashboard.invalidate(); void utils.finance.transactions.invalidate(); void utils.finance.goals.invalidate(); };
  const data = dashboard.data;
  const selectedYear = Number(month.slice(0, 4));
  const yearFrom = `${selectedYear}-01-01T00:00:00.000Z`;
  const yearTo = `${selectedYear}-12-31T23:59:59.999Z`;
  const periodFrom = `${month}-01T00:00:00.000Z`;
  const periodTo = `${month}-31T23:59:59.999Z`;
  const dreRows = trpc.finance.temporalDre.useQuery({ from: yearFrom, to: yearTo, mode: dreMode, ...(selectedProductId ? { productId: selectedProductId } : {}) });
  const goalProgress = trpc.finance.goalProgress.useQuery({ year: selectedYear, ...(selectedProductId ? { productId: selectedProductId } : {}) });
  const infrastructure = trpc.finance.infrastructureBreakdown.useQuery({ from: periodFrom, to: periodTo, ...(selectedProductId ? { productId: selectedProductId } : {}) });
  const contractMargins = trpc.finance.contractMargins.useQuery({ from: periodFrom, to: periodTo, ...(selectedProductId ? { productId: selectedProductId } : {}) });
  const profitability = trpc.finance.customerProfitability.useQuery({ from: periodFrom, to: periodTo, ...(selectedProductId ? { productId: selectedProductId } : {}) });
  const invoiceInput = useMemo(() => ({ ...(invoiceSearch ? { search: invoiceSearch } : {}), ...(invoiceStatus !== "all" ? { paymentStatus: invoiceStatus } : {}), ...(invoiceFrom ? { from: new Date(`${invoiceFrom}T00:00:00.000Z`).toISOString() } : {}), ...(invoiceTo ? { to: new Date(`${invoiceTo}T23:59:59.999Z`).toISOString() } : {}) }), [invoiceSearch, invoiceStatus, invoiceFrom, invoiceTo]);
  const invoices = trpc.finance.invoices.useQuery(invoiceInput);
  const page = location === "/lancamentos" ? "launch" : location === "/metas" ? "goals" : location === "/cadastro" ? "operations" : location === "/contratos" ? "contracts" : location === "/catalogo" ? "catalog" : location === "/notas-fiscais" ? "invoices" : "overview";
  const sectionTitle = page === "launch" ? "Central de lançamentos" : page === "goals" ? "Cockpit de metas" : page === "operations" ? "Cadastros operacionais" : page === "contracts" ? "Contratos e licenças" : page === "catalog" ? "Produtos, planos e provedores" : page === "invoices" ? "Notas fiscais" : "Visão executiva";
  return <div className="min-h-[calc(100vh-2rem)] bg-[#f7f8fb] text-slate-950 -m-4 p-4 md:p-8"><div className="mx-auto max-w-7xl space-y-6"><header className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><div className="flex items-center gap-2 text-sm font-medium text-blue-700"><CircleDollarSign className="h-4 w-4" />Elo Finance Hub</div><h1 className="mt-2 text-3xl font-semibold tracking-tight">{sectionTitle}</h1><p className="mt-1 max-w-2xl text-sm text-slate-500">Registre os fatos financeiros reais e acompanhe cada produto SaaS sem estimativas ocultas.</p></div><div className="flex flex-wrap items-center gap-2"><Select value={productId} onValueChange={setProductId}><SelectTrigger className="w-[210px] bg-white"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="group">Grupo Elo — consolidado</SelectItem>{catalog.products.map(product => <SelectItem key={product.id} value={String(product.id)}>{product.name}</SelectItem>)}</SelectContent></Select><Input className="w-[150px] bg-white" type="month" value={month} onChange={e => setMonth(e.target.value)} /><Button variant="outline" onClick={refresh} aria-label="Atualizar dados"><RefreshCw className="h-4 w-4" /></Button></div></header>
    {page === "overview" && <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"> <KpiCard title="MRR ativo" value={money(data?.mrr)} helper="Contratos ativos registrados" icon={WalletCards} tone="blue" /><KpiCard title="Receita recebida" value={money(data?.received)} helper={`Lançamentos confirmados em ${month}`} icon={ArrowDownRight} tone="emerald" /><KpiCard title="Margem bruta" value={pct(data?.grossMargin)} helper="Receita recebida menos COGS real" icon={BarChart3} tone="emerald" /><KpiCard title="Net Burn Rate" value={money(data?.netBurnRate)} helper="Saídas menos entradas no período" icon={Calculator} tone={data?.netBurnRate && data.netBurnRate > 0 ? "rose" : "blue"} /><KpiCard title="Runway" value={data?.runway == null ? "—" : `${data.runway.toFixed(1)} meses`} helper={data?.runway == null ? "Sem queima líquida calculável" : "Saldo de caixa / queima mensal"} icon={Landmark} tone="amber" /></div><div className="grid gap-6 lg:grid-cols-[1.25fr_0.75fr]"><Card className="border-border/70 shadow-sm"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><Calculator className="h-4 w-4 text-blue-600" />DRE gerencial do período</CardTitle></CardHeader><CardContent><div className="space-y-3 text-sm"><div className="flex justify-between"><span className="text-muted-foreground">Receita recebida</span><strong className="text-emerald-700">{money(data?.received)}</strong></div><div className="flex justify-between"><span className="text-muted-foreground">(-) COGS de infraestrutura</span><strong>{money(data?.cogs)}</strong></div><div className="flex justify-between border-t pt-3"><span>Margem bruta</span><strong>{money((data?.received ?? 0) - (data?.cogs ?? 0))}</strong></div><div className="flex justify-between"><span className="text-muted-foreground">(-) OpEx lançado</span><strong>{money(data?.opex)}</strong></div><div className="flex justify-between border-t pt-3 text-base"><span>Resultado operacional do período</span><strong className={(data?.received ?? 0) - (data?.cogs ?? 0) - (data?.opex ?? 0) >= 0 ? "text-emerald-700" : "text-rose-700"}>{money((data?.received ?? 0) - (data?.cogs ?? 0) - (data?.opex ?? 0))}</strong></div></div><p className="mt-5 text-xs text-muted-foreground">A DRE exibida usa apenas lançamentos confirmados. Impostos serão aplicados quando uma regra tributária configurada estiver vinculada ao produto.</p></CardContent></Card><Card className="border-border/70 shadow-sm"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><ShieldAlert className="h-4 w-4 text-amber-600" />Qualidade da base</CardTitle></CardHeader><CardContent className="space-y-4"><div className="rounded-lg bg-muted/40 p-4"><p className="text-2xl font-semibold">{data?.transactionCount ?? 0}</p><p className="text-sm text-muted-foreground">lançamentos no período selecionado</p></div><div className="rounded-lg border border-amber-200 bg-amber-50 p-4"><div className="flex items-end justify-between gap-3"><div><p className="text-2xl font-semibold text-amber-900">{data?.pendingInvoiceAttachments ?? 0}</p><p className="text-sm text-amber-800">entradas sem nota fiscal anexada</p></div><p className="text-right text-xs text-amber-700">mês selecionado<br /><span className="font-semibold">{data?.incomeCount ? `${(((data?.pendingInvoiceAttachments ?? 0) / data.incomeCount) * 100).toFixed(1)}%` : "—"}</span></p></div></div>{(data?.transactionCount ?? 0) === 0 ? <div className="flex gap-3 text-sm text-muted-foreground"><ShieldAlert className="mt-0.5 h-4 w-4 shrink-0 text-amber-600" /><p>O painel está sem fatos financeiros neste período. Registre uma entrada ou saída para habilitar os indicadores reais.</p></div> : <p className="text-sm text-muted-foreground">Os KPIs estão sendo calculados sobre dados persistidos e confirmados.</p>}</CardContent></Card></div></>}
    {page === "overview" && <CustomerProfitabilityWidget data={profitability.data ?? { top: [], bottom: [] }} />}
    {page === "overview" && <ReportingVisuals dreRows={dreRows.data ?? []} infrastructure={infrastructure.data ?? []} goals={goalProgress.data ?? []} margins={contractMargins.data ?? []} dreMode={dreMode} setDreMode={setDreMode} reportLabel={`${month} · ${productId === "group" ? "Grupo Elo" : "produto selecionado"}`} />}
    {page === "operations" && <OperationsForm operations={operationsQuery.data ?? { customers: [], bankAccounts: [] }} onDone={() => { void operationsQuery.refetch(); refresh(); }} />}
    {page === "catalog" && <CatalogForm catalog={catalog} onDone={() => { void utils.finance.catalog.invalidate(); refresh(); }} />} 
    {page === "invoices" && <InvoiceSection transactions={transactions.data ?? []} invoices={invoices.data ?? []} filters={{ search: invoiceSearch, status: invoiceStatus, from: invoiceFrom, to: invoiceTo }} onFiltersChange={{ setSearch: setInvoiceSearch, setStatus: setInvoiceStatus, setFrom: setInvoiceFrom, setTo: setInvoiceTo }} onDone={() => { void invoices.refetch(); }} />}
    {page === "contracts" && <ContractsForm catalog={catalog} operations={operationsQuery.data ?? { customers: [], contracts: [], licenses: [] }} onDone={() => { void operationsQuery.refetch(); refresh(); }} />}
    {page === "launch" && <Card className="border-border/70 shadow-sm"><CardHeader><CardTitle className="text-base">Novo lançamento financeiro</CardTitle></CardHeader><CardContent><LaunchForm catalog={catalog} operations={operationsQuery.data ?? { customers: [], contracts: [] }} onDone={() => { setShowLaunch(false); refresh(); }} /></CardContent></Card>}
    {page === "goals" && <div className="space-y-6"><GoalForm catalog={catalog} year={goalYear} onDone={refresh} /><Card className="border-border/70 shadow-sm"><CardHeader className="flex flex-row items-center justify-between"><CardTitle className="text-base">Metas configuradas</CardTitle><Input className="w-28" type="number" value={goalYear} onChange={e => setGoalYear(Number(e.target.value))} /></CardHeader><CardContent>{goals.isLoading ? <Loader2 className="h-5 w-5 animate-spin" /> : goals.data?.length ? <div className="grid gap-3 md:grid-cols-4">{goals.data.map(goal => <div key={goal.id} className="rounded-xl border p-4"><div className="flex items-center justify-between"><Badge variant="secondary">{goal.quarter}</Badge><Target className="h-4 w-4 text-blue-600" /></div><p className="mt-4 text-lg font-semibold">{money(goal.targetMrr)}</p><p className="text-xs text-muted-foreground">meta de MRR</p><p className="mt-3 text-sm">{goal.targetNewCustomers} novos clientes</p></div>)}</div> : <EmptyState title="Nenhuma meta cadastrada" detail="Defina metas por trimestre para começar o acompanhamento do plano comercial." />}</CardContent></Card></div>}
    {page !== "goals" && page !== "operations" && page !== "contracts" && page !== "invoices" && <Card className="border-border/70 shadow-sm"><CardHeader className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><CardTitle className="text-base">Histórico de lançamentos — {month}</CardTitle><div className="flex flex-wrap gap-2"><Input className="w-40" value={historyCategory} onChange={e => setHistoryCategory(e.target.value)} placeholder="Categoria" /><Select value={historyProvider} onValueChange={setHistoryProvider}><SelectTrigger className="w-44"><SelectValue placeholder="Provedor" /></SelectTrigger><SelectContent><SelectItem value="all">Todos os provedores</SelectItem>{catalog.providers.map(provider => <SelectItem key={provider.id} value={String(provider.id)}>{provider.name}</SelectItem>)}</SelectContent></Select><Tabs value={historyType} onValueChange={value => setHistoryType(value as typeof historyType)}><TabsList><TabsTrigger value="all">Todos</TabsTrigger><TabsTrigger value="income">Entradas</TabsTrigger><TabsTrigger value="expense">Saídas</TabsTrigger></TabsList></Tabs></div></CardHeader><CardContent>{transactions.isLoading ? <Loader2 className="h-5 w-5 animate-spin" /> : !transactions.data?.length ? <EmptyState title="Nenhum lançamento encontrado" detail="Use a Central de lançamentos para registrar fatos financeiros reais. O sistema não cria dados fictícios." /> : <div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="border-b text-xs uppercase text-muted-foreground"><tr><th className="pb-3">Data</th><th className="pb-3">Descrição</th><th className="pb-3">Produto</th><th className="pb-3">Categoria</th><th className="pb-3 text-right">Valor</th></tr></thead><tbody>{transactions.data.map(row => <tr key={row.transaction.id} className="border-b last:border-0"><td className="py-3">{new Date(row.transaction.occurredAt).toLocaleDateString("pt-BR")}</td><td className="py-3 font-medium">{row.transaction.description}</td><td className="py-3 text-muted-foreground">{row.productName ?? "Grupo Elo"}</td><td className="py-3 text-muted-foreground">{row.transaction.category}{row.providerName ? ` · ${row.providerName}` : ""}</td><td className={`py-3 text-right font-semibold ${row.transaction.type === "income" ? "text-emerald-700" : "text-rose-700"}`}>{row.transaction.type === "income" ? "+" : "-"}{money(row.transaction.amount)}</td></tr>)}</tbody></table></div>}</CardContent></Card>}
  </div></div>;
}

function CustomerProfitabilityWidget({ data }: { data: { top: any[]; bottom: any[] } }) { const list = (items: any[]) => items.length ? <div className="space-y-3">{items.map((item, index) => <div key={item.customerId} className="flex items-center justify-between gap-3 rounded-lg border p-3"><div className="min-w-0"><p className="truncate text-sm font-medium">{index + 1}. {item.customerName}</p><p className="text-xs text-muted-foreground">Receita {money(item.revenue)} · COGS {money(item.cogs)}</p></div><div className="text-right"><p className={`text-sm font-semibold ${item.contribution >= 0 ? "text-emerald-700" : "text-rose-700"}`}>{money(item.contribution)}</p><p className="text-xs text-muted-foreground">{pct(item.marginPercent)}</p></div></div>)}</div> : <EmptyState title="Sem rentabilidade calculada" detail="Registre receitas e custos confirmados vinculados a clientes." />; return <Card><CardHeader><CardTitle>Rentabilidade por cliente</CardTitle><p className="text-sm text-muted-foreground">Os cinco maiores resultados e os cinco menores percentuais de margem no período.</p></CardHeader><CardContent><div className="grid gap-6 lg:grid-cols-2"><div><p className="mb-3 text-xs font-semibold uppercase tracking-wide text-emerald-700">5 mais lucrativos</p>{list(data.top)}</div><div><p className="mb-3 text-xs font-semibold uppercase tracking-wide text-rose-700">5 com menor margem</p>{list(data.bottom)}</div></div></CardContent></Card>; }
function InvoiceSection({ transactions, invoices, filters, onFiltersChange, onDone }: { transactions: any[]; invoices: any[]; filters: { search: string; status: "all" | "confirmed" | "pending" | "cancelled"; from: string; to: string }; onFiltersChange: { setSearch: (value: string) => void; setStatus: (value: "all" | "confirmed" | "pending" | "cancelled") => void; setFrom: (value: string) => void; setTo: (value: string) => void }; onDone: () => void }) {
  const [form, setForm] = useState({ transactionId: "", number: "", series: "", issueDate: isoToday, accessKey: "", notes: "" });
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [uploadingId, setUploadingId] = useState<number | null>(null);
  const [reviewItem, setReviewItem] = useState<any | null>(null);
  const [reviewForm, setReviewForm] = useState({ amount: "", issueDate: "", supplierName: "", issuerDocument: "", recipientDocument: "" });
  const cnpjValid = !reviewForm.issuerDocument || processamento_validateCnpj(reviewForm.issuerDocument);
  const create = trpc.finance.createInvoice.useMutation({ onSuccess: () => { toast.success("Nota fiscal vinculada"); onDone(); }, onError: error => toast.error(error.message) });
  const upload = trpc.finance.uploadInvoicePdf.useMutation({ onSuccess: () => { toast.success("PDF anexado à nota fiscal"); setSelectedFile(null); setUploadingId(null); onDone(); }, onError: error => { setUploadingId(null); toast.error(error.message); } });
  const getPdfUrl = trpc.finance.invoicePdfUrl.useMutation({ onSuccess: result => window.open(result.url, "_blank", "noopener,noreferrer"), onError: error => toast.error(error.message) });
  const review = trpc.finance.reviewInvoiceExtraction.useMutation({ onSuccess: () => { toast.success("Sugestão fiscal revisada"); setReviewItem(null); onDone(); }, onError: error => toast.error(error.message) });
  const remove = trpc.finance.deleteInvoice.useMutation({ onSuccess: onDone, onError: error => toast.error(error.message) });
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!form.transactionId || !form.number) return toast.error("Informe o lançamento e o número da nota"); create.mutate({ transactionId: Number(form.transactionId), number: form.number, series: form.series || undefined, issueDate: new Date(`${form.issueDate}T12:00:00.000Z`).toISOString(), accessKey: form.accessKey || undefined, notes: form.notes || undefined }); };
  const uploadPdf = async (invoiceId: number) => { if (!selectedFile) return toast.error("Selecione um PDF antes de anexar"); if (selectedFile.type !== "application/pdf" || !selectedFile.name.toLowerCase().endsWith(".pdf")) return toast.error("Selecione um arquivo PDF válido"); if (selectedFile.size > 10 * 1024 * 1024) return toast.error("O PDF deve ter até 10 MB"); const bytes = new Uint8Array(await selectedFile.arrayBuffer()); if (new TextDecoder().decode(bytes.slice(0, 4)) !== "%PDF") return toast.error("O arquivo não parece ser um PDF válido"); let binary = ""; bytes.forEach(byte => { binary += String.fromCharCode(byte); }); setUploadingId(invoiceId); upload.mutate({ invoiceId, base64: btoa(binary), fileName: selectedFile.name, fileSize: selectedFile.size, contentType: "application/pdf" }); };
  const reviewInvoice = (item: any) => { setReviewItem(item); setReviewForm({ amount: item.invoice.extractedAmount ?? "", issueDate: item.invoice.extractedIssueDate ? new Date(item.invoice.extractedIssueDate).toISOString().slice(0, 10) : "", supplierName: item.invoice.extractedSupplierName ?? "", issuerDocument: item.invoice.extractedIssuerDocument ?? "", recipientDocument: item.invoice.extractedRecipientDocument ?? "" }); };
  const saveReview = () => { if (!cnpjValid) return toast.error("Corrija o CNPJ inválido antes de salvar"); review.mutate({ invoiceId: reviewItem.invoice.id, amount: reviewForm.amount.trim() ? Number(reviewForm.amount.replace(",", ".")) : null, issueDate: reviewForm.issueDate ? new Date(`${reviewForm.issueDate}T12:00:00.000Z`).toISOString() : null, supplierName: reviewForm.supplierName.trim() || null, issuerDocument: reviewForm.issuerDocument.trim() || null, recipientDocument: reviewForm.recipientDocument.trim() || null }); };
  return <div className="space-y-6"><Card><CardHeader><CardTitle>Vincular nota fiscal a lançamento</CardTitle><p className="text-sm text-muted-foreground">Registre os dados da nota e, depois, anexe o PDF original ao registro.</p></CardHeader><CardContent><form className="grid gap-4 md:grid-cols-2" onSubmit={submit}><div className="space-y-2"><Label>Lançamento</Label><Select value={form.transactionId} onValueChange={value => setForm({ ...form, transactionId: value })}><SelectTrigger><SelectValue placeholder="Selecione um lançamento" /></SelectTrigger><SelectContent>{transactions.map(row => <SelectItem key={row.transaction.id} value={String(row.transaction.id)}>{row.transaction.description} · {money(row.transaction.amount)}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Número da nota</Label><Input value={form.number} onChange={event => setForm({ ...form, number: event.target.value })} /></div><div className="space-y-2"><Label>Série</Label><Input value={form.series} onChange={event => setForm({ ...form, series: event.target.value })} /></div><div className="space-y-2"><Label>Data de emissão</Label><Input type="date" value={form.issueDate} onChange={event => setForm({ ...form, issueDate: event.target.value })} /></div><div className="space-y-2 md:col-span-2"><Label>Chave de acesso, se aplicável</Label><Input maxLength={44} value={form.accessKey} onChange={event => setForm({ ...form, accessKey: event.target.value })} /></div><div className="space-y-2 md:col-span-2"><Label>Observações</Label><Input value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><Button type="submit" disabled={create.isPending}>{create.isPending ? "Salvando…" : "Vincular nota fiscal"}</Button></form></CardContent></Card><Card><CardHeader><CardTitle>Notas fiscais vinculadas</CardTitle><div className="grid gap-3 pt-2 sm:grid-cols-2 lg:grid-cols-4"><Input aria-label="Buscar fornecedor ou cliente" placeholder="Fornecedor, cliente ou número" value={filters.search} onChange={event => onFiltersChange.setSearch(event.target.value)} /><Input aria-label="Data inicial" type="date" value={filters.from} onChange={event => onFiltersChange.setFrom(event.target.value)} /><Input aria-label="Data final" type="date" value={filters.to} onChange={event => onFiltersChange.setTo(event.target.value)} /><Select value={filters.status} onValueChange={value => onFiltersChange.setStatus(value as typeof filters.status)}><SelectTrigger><SelectValue placeholder="Status do pagamento" /></SelectTrigger><SelectContent><SelectItem value="all">Todos os pagamentos</SelectItem><SelectItem value="confirmed">Confirmado</SelectItem><SelectItem value="pending">Pendente</SelectItem><SelectItem value="cancelled">Cancelado</SelectItem></SelectContent></Select></div></CardHeader><CardContent>{invoices.length ? <div className="space-y-4"><div className="flex flex-wrap items-end gap-3 rounded-lg border bg-muted/20 p-3"><div className="min-w-[240px] flex-1 space-y-1"><Label htmlFor="invoice-pdf">PDF da nota fiscal</Label><Input id="invoice-pdf" type="file" accept="application/pdf,.pdf" onChange={event => setSelectedFile(event.target.files?.[0] ?? null)} /></div><p className="text-xs text-muted-foreground">PDF, máximo de 10 MB. O arquivo é validado no navegador e no servidor.</p></div><div className="overflow-x-auto"><table className="w-full min-w-[780px] text-left text-sm"><thead className="border-b text-xs uppercase text-muted-foreground"><tr><th className="pb-3">Número</th><th className="pb-3">Lançamento</th><th className="pb-3">Emissão</th><th className="pb-3">Extração IA</th><th className="pb-3">PDF</th><th className="pb-3">Ações</th></tr></thead><tbody>{invoices.map(item => <tr key={item.invoice.id} className="border-b last:border-0"><td className="py-3 font-medium">{item.invoice.number}</td><td className="py-3">{item.transaction.description}</td><td className="py-3">{new Date(item.invoice.issueDate).toLocaleDateString("pt-BR")}</td><td className="py-3"><div className="text-xs"><span className="font-medium">{item.invoice.extractionStatus === "completed" ? "Sugestão pronta" : item.invoice.extractionStatus === "failed" ? "Falhou" : item.invoice.extractionStatus === "pending" ? "Aguardando" : "Revisada"}</span>{item.invoice.extractedSupplierName ? <p className="text-muted-foreground">{item.invoice.extractedSupplierName} · {item.invoice.extractedIssuerDocument ?? "CNPJ não identificado"}</p> : null}{item.invoice.extractedAmount ? <p className="text-muted-foreground">{money(item.invoice.extractedAmount)}{item.invoice.extractedIssueDate ? ` · ${new Date(item.invoice.extractedIssueDate).toLocaleDateString("pt-BR")}` : ""}</p> : null}</div></td><td className="py-3">{item.invoice.fileKey ? <Button variant="outline" size="sm" onClick={() => getPdfUrl.mutate({ invoiceId: item.invoice.id })}>Visualizar PDF</Button> : <span className="text-xs text-muted-foreground">Sem anexo</span>}</td><td className="py-3"><div className="flex flex-wrap gap-2"><Button variant="secondary" size="sm" disabled={!selectedFile || uploadingId === item.invoice.id} onClick={() => { void uploadPdf(item.invoice.id); }}>{uploadingId === item.invoice.id ? "Anexando…" : "Anexar PDF"}</Button>{item.invoice.extractionStatus === "completed" ? <Button variant="outline" size="sm" onClick={() => reviewInvoice(item)}>Revisar sugestão</Button> : null}<Button variant="ghost" size="sm" onClick={() => remove.mutate({ id: item.invoice.id })}>Desvincular</Button></div></td></tr>)}</tbody></table></div></div> : <EmptyState title="Nenhuma nota fiscal vinculada" detail="Associe uma nota fiscal a um lançamento para criar a trilha documental." />}</CardContent></Card><Dialog open={Boolean(reviewItem)} onOpenChange={open => { if (!open) setReviewItem(null); }}><DialogContent><DialogHeader><DialogTitle>Revisar dados extraídos</DialogTitle><DialogDescription>Confirme ou corrija as sugestões da IA. Elas só serão marcadas como revisadas após este salvamento.</DialogDescription></DialogHeader>{reviewItem ? <div className="grid gap-4 py-2 sm:grid-cols-2"><div className="space-y-2"><Label>Fornecedor</Label><Input value={reviewForm.supplierName} onChange={event => setReviewForm({ ...reviewForm, supplierName: event.target.value })} /></div><div className="space-y-2"><Label>Valor</Label><Input type="number" min="0" step="0.01" value={reviewForm.amount} onChange={event => setReviewForm({ ...reviewForm, amount: event.target.value })} /></div><div className="space-y-2"><Label>Data de emissão</Label><Input type="date" value={reviewForm.issueDate} onChange={event => setReviewForm({ ...reviewForm, issueDate: event.target.value })} /></div><div className="space-y-2"><Label>CNPJ do fornecedor</Label><Input value={reviewForm.issuerDocument} onChange={event => setReviewForm({ ...reviewForm, issuerDocument: event.target.value })} aria-invalid={!cnpjValid} />{reviewForm.issuerDocument && !cnpjValid ? <Alert variant="destructive"><AlertDescription>Este CNPJ não possui formato ou dígitos verificadores válidos.</AlertDescription></Alert> : <p className="text-xs text-muted-foreground">Informe 14 dígitos; a máscara é aceita.</p>}</div><div className="space-y-2 sm:col-span-2"><Label>CNPJ do destinatário</Label><Input value={reviewForm.recipientDocument} onChange={event => setReviewForm({ ...reviewForm, recipientDocument: event.target.value })} /></div></div> : null}<DialogFooter><Button variant="outline" onClick={() => setReviewItem(null)}>Cancelar</Button><Button disabled={review.isPending || !cnpjValid} onClick={saveReview}>{review.isPending ? "Salvando…" : "Salvar revisão"}</Button></DialogFooter></DialogContent></Dialog></div>;
}
function ReportingVisuals({ dreRows, infrastructure, goals, margins, dreMode, setDreMode, reportLabel }: { dreRows: any[]; infrastructure: any[]; goals: any[]; margins: any[]; dreMode: "month" | "quarter" | "year"; setDreMode: (value: "month" | "quarter" | "year") => void; reportLabel: string }) {
  const dre = dreRows;
  const goalChart = goals.map(goal => ({ period: goal.quarter, target: Number(goal.targetMrr), realized: Number(goal.actualMrr ?? 0), received: Number(goal.actualReceived ?? 0), attainment: goal.mrrAttainment }));
  const dreRowsForExport = dre.map(row => [row.period, money(row.revenue), money(row.taxes), money(row.cogs), money(row.opex), money(row.ebitda)]);
  const marginRowsForExport = margins.map(item => [item.code, item.customerName, item.productName, money(item.revenue), money(item.directCogs), money(item.allocatedCogs), money(item.contribution), pct(item.marginPercent)]);
  return <div className="space-y-6">
    <div className="grid gap-6 xl:grid-cols-[1.4fr_0.6fr]">
      <Card><CardHeader><div className="flex flex-wrap items-start justify-between gap-3"><div><CardTitle>DRE temporal</CardTitle><p className="text-sm text-muted-foreground">Dados reais com impostos configurados.</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" size="sm" disabled={!dre.length} onClick={() => downloadCsv(`dre-${dreMode}-${reportLabel.replaceAll(" ", "-")}.csv`, ["Período", "Receita", "Impostos", "COGS", "OpEx", "EBITDA"], dreRowsForExport)}>CSV</Button><Button variant="outline" size="sm" disabled={!dre.length} onClick={() => exportPdf(`dre-${dreMode}.pdf`, "DRE temporal", reportLabel, ["Período", "Receita", "Impostos", "COGS", "OpEx", "EBITDA"], dreRowsForExport)}>PDF</Button><Select value={dreMode} onValueChange={value => setDreMode(value as typeof dreMode)}><SelectTrigger className="w-32"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="month">Mensal</SelectItem><SelectItem value="quarter">Trimestral</SelectItem><SelectItem value="year">Anual</SelectItem></SelectContent></Select></div></div></CardHeader><CardContent>{dre.length ? <ResponsiveContainer width="100%" height={280}><LineChart data={dre}><CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" /><XAxis dataKey="period" /><YAxis tickFormatter={value => `R$${value}`} /><Tooltip formatter={(value: number) => money(value)} /><Line type="monotone" dataKey="revenue" name="Receita" stroke="#059669" strokeWidth={3} /><Line type="monotone" dataKey="taxes" name="Impostos" stroke="#a855f7" strokeWidth={2} /><Line type="monotone" dataKey="cogs" name="COGS" stroke="#ef4444" strokeWidth={2} /><Line type="monotone" dataKey="opex" name="OpEx" stroke="#f59e0b" strokeWidth={2} /><Line type="monotone" dataKey="ebitda" name="EBITDA" stroke="#2563eb" strokeWidth={3} /></LineChart></ResponsiveContainer> : <EmptyState title="DRE sem dados" detail="Registre lançamentos confirmados para visualizar a evolução temporal." />}</CardContent></Card>
      <Card><CardHeader><CardTitle>Rateio de infraestrutura</CardTitle><p className="text-sm text-muted-foreground">Custo distribuído no período selecionado.</p></CardHeader><CardContent>{infrastructure.length ? <ResponsiveContainer width="100%" height={280}><PieChart><Pie data={infrastructure} dataKey="amount" nameKey="displayLabel" cx="50%" cy="50%" outerRadius={92} label={({ displayLabel }) => displayLabel}><Cell fill="#2563eb" /><Cell fill="#059669" /><Cell fill="#f59e0b" /><Cell fill="#8b5cf6" /></Pie><Tooltip formatter={(value: number) => money(value)} /></PieChart></ResponsiveContainer> : <EmptyState title="Sem rateio calculado" detail="Custos elegíveis serão distribuídos quando houver licenças ativas e lançamentos reais." />}</CardContent></Card>
    </div>
    <div className="grid gap-6 xl:grid-cols-[0.9fr_1.1fr]">
      <Card><CardHeader><CardTitle>Evolução das metas financeiras</CardTitle><p className="text-sm text-muted-foreground">Meta, MRR realizado e receita recebida por trimestre.</p></CardHeader><CardContent>{goalChart.length ? <><ResponsiveContainer width="100%" height={260}><BarChart data={goalChart}><CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" /><XAxis dataKey="period" /><YAxis tickFormatter={value => `R$${value}`} /><Tooltip formatter={(value: number) => money(value)} /><Bar dataKey="target" name="Meta MRR" fill="#2563eb" radius={[6, 6, 0, 0]} /><Bar dataKey="realized" name="MRR realizado" fill="#10b981" radius={[6, 6, 0, 0]} /><Bar dataKey="received" name="Receita recebida" fill="#f59e0b" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer><div className="mt-4 grid gap-2 sm:grid-cols-2">{goalChart.map(item => <div key={item.period} className="rounded-lg bg-muted/40 p-3 text-xs"><div className="flex justify-between font-medium"><span>{item.period} · atingimento MRR</span><span className={item.attainment != null && item.attainment >= 100 ? "text-emerald-700" : "text-amber-700"}>{item.attainment == null ? "—" : `${Number(item.attainment).toFixed(1)}%`}</span></div><p className="mt-1 text-muted-foreground">Recebido: {money(item.received)} · MRR realizado: {money(item.realized)}</p></div>)}</div></> : <EmptyState title="Metas não configuradas" detail="Defina metas por trimestre no cockpit para habilitar este gráfico." />}</CardContent></Card>
      <Card><CardHeader><div className="flex flex-wrap items-start justify-between gap-3"><div><CardTitle>Margem por contrato</CardTitle><p className="text-sm text-muted-foreground">Receita menos COGS direto e rateado no período.</p></div><div className="flex gap-2"><Button variant="outline" size="sm" disabled={!margins.length} onClick={() => downloadCsv(`margem-contratos-${reportLabel.replaceAll(" ", "-")}.csv`, ["Contrato", "Cliente", "Produto", "Receita", "COGS direto", "COGS rateado", "Contribuição", "Margem %"], marginRowsForExport)}>CSV</Button><Button variant="outline" size="sm" disabled={!margins.length} onClick={() => exportPdf("margem-contratos.pdf", "Margem por contrato", reportLabel, ["Contrato", "Cliente", "Produto", "Receita", "COGS direto", "COGS rateado", "Contribuição", "Margem %"], marginRowsForExport)}>PDF</Button></div></div></CardHeader><CardContent>{margins.length ? <div className="overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead className="border-b text-xs uppercase text-muted-foreground"><tr><th className="pb-3">Contrato</th><th className="pb-3">Cliente</th><th className="pb-3 text-right">Receita</th><th className="pb-3 text-right">COGS</th><th className="pb-3 text-right">Margem</th></tr></thead><tbody>{margins.map(item => <tr key={item.contractId} className="border-b last:border-0"><td className="py-3 font-medium">{item.code}</td><td className="py-3">{item.customerName ?? "—"}</td><td className="py-3 text-right">{money(item.revenue)}</td><td className="py-3 text-right">{money(item.directCogs + item.allocatedCogs)}</td><td className={`py-3 text-right font-semibold ${item.contribution >= 0 ? "text-emerald-700" : "text-rose-700"}`}>{item.marginPercent == null ? "—" : `${item.marginPercent.toFixed(1)}%`}</td></tr>)}</tbody></table></div> : <EmptyState title="Margem contratual sem dados" detail="Vincule lançamentos de receita e custos a contratos para calcular a margem." />}</CardContent></Card>
    </div>
  </div>;
}

function processamento_buildTemporalDreClient(rows: any[]) { return rows.map(row => ({ period: row.period ?? row.date?.slice(0, 7), revenue: Number(row.income ?? row.revenue ?? 0), taxes: Number(row.taxes ?? 0), cogs: Number(row.cogs ?? 0), opex: Number(row.opex ?? 0), ebitda: Number(row.ebitda ?? 0) })); }

function CatalogForm({ catalog, onDone }: { catalog: { products: any[]; providers: any[] }; onDone: () => void }) { const product = trpc.finance.createProduct.useMutation({ onSuccess: () => { toast.success("SaaS cadastrado"); onDone(); }, onError: e => toast.error(e.message) }); const provider = trpc.finance.createProvider.useMutation({ onSuccess: () => { toast.success("Provedor cadastrado"); onDone(); }, onError: e => toast.error(e.message) }); const [p, setP] = useState({ name: "", slug: "", category: "", sharedBaseMonthlyCost: "0" }); const [v, setV] = useState({ name: "", code: "" }); return <div className="grid gap-6 lg:grid-cols-2"><Card><CardHeader><CardTitle>Novo produto SaaS</CardTitle></CardHeader><CardContent><form className="space-y-4" onSubmit={e => { e.preventDefault(); if (!p.name || !p.slug) return toast.error("Informe nome e slug"); product.mutate({ ...p, sharedInfrastructure: Number(p.sharedBaseMonthlyCost) > 0, sharedBaseMonthlyCost: Number(p.sharedBaseMonthlyCost) }); }}><Input aria-label="Nome do produto SaaS" placeholder="Nome do novo SaaS" value={p.name} onChange={e => setP({ ...p, name: e.target.value })} /><Input aria-label="Slug do produto SaaS" placeholder="slug-do-produto" value={p.slug} onChange={e => setP({ ...p, slug: e.target.value })} /><Input aria-label="Categoria" placeholder="Categoria" value={p.category} onChange={e => setP({ ...p, category: e.target.value })} /><Input aria-label="Custo base compartilhado" type="number" min="0" step="0.01" placeholder="Custo base mensal compartilhado" value={p.sharedBaseMonthlyCost} onChange={e => setP({ ...p, sharedBaseMonthlyCost: e.target.value })} /><Button type="submit">Cadastrar SaaS</Button></form><p className="mt-4 text-xs text-muted-foreground">{catalog.products.length} produto(s) no catálogo.</p></CardContent></Card><Card><CardHeader><CardTitle>Novo provedor de infraestrutura</CardTitle></CardHeader><CardContent><form className="space-y-4" onSubmit={e => { e.preventDefault(); if (!v.name || !v.code) return toast.error("Informe nome e código"); provider.mutate(v); }}><Input aria-label="Nome do provedor" placeholder="GCP, AWS, Azure, Cloudflare ou API" value={v.name} onChange={e => setV({ ...v, name: e.target.value })} /><Input aria-label="Código do provedor" placeholder="gcp" value={v.code} onChange={e => setV({ ...v, code: e.target.value })} /><Button type="submit">Cadastrar provedor</Button></form><p className="mt-4 text-xs text-muted-foreground">{catalog.providers.length} provedor(es) disponível(is). Planos podem ser vinculados aos produtos na próxima etapa do catálogo.</p></CardContent></Card></div>; }

function ContractsForm({ catalog, operations, onDone }: { catalog: { products: any[] }; operations: { customers: any[]; contracts?: any[]; licenses?: any[] }; onDone: () => void }) {
  const createContract = trpc.finance.createContract.useMutation({ onSuccess: () => { toast.success("Contrato cadastrado"); onDone(); }, onError: error => toast.error(error.message) });
  const createLicense = trpc.finance.createLicense.useMutation({ onSuccess: () => { toast.success("Licença cadastrada"); onDone(); }, onError: error => toast.error(error.message) });
  const [contract, setContract] = useState({ customerId: "", productId: "", code: "", billingCycle: "monthly" as "monthly" | "quarterly" | "annual", mrr: "" });
  const [license, setLicense] = useState({ contractId: "", licenseKey: "", activeSeats: "1" });
  return <div className="space-y-6"><Card><CardHeader><CardTitle>Novo contrato SaaS</CardTitle></CardHeader><CardContent><form className="grid gap-4 md:grid-cols-2 lg:grid-cols-3" onSubmit={e => { e.preventDefault(); if (!contract.customerId || !contract.productId || !contract.code || !contract.mrr) return toast.error("Preencha cliente, produto, código e MRR"); createContract.mutate({ customerId: Number(contract.customerId), productId: Number(contract.productId), code: contract.code, billingCycle: contract.billingCycle, monthlyRecurringRevenue: Number(contract.mrr), startDate: new Date().toISOString(), paymentStatus: "unknown" }); }}><Select value={contract.customerId} onValueChange={value => setContract({ ...contract, customerId: value })}><SelectTrigger><SelectValue placeholder="Cliente" /></SelectTrigger><SelectContent>{operations.customers.map(customer => <SelectItem key={customer.id} value={String(customer.id)}>{customer.legalName}</SelectItem>)}</SelectContent></Select><Select value={contract.productId} onValueChange={value => setContract({ ...contract, productId: value })}><SelectTrigger><SelectValue placeholder="Produto SaaS" /></SelectTrigger><SelectContent>{catalog.products.filter(product => product.slug !== "grupo-elo").map(product => <SelectItem key={product.id} value={String(product.id)}>{product.name}</SelectItem>)}</SelectContent></Select><Input placeholder="Código do contrato" value={contract.code} onChange={e => setContract({ ...contract, code: e.target.value })} /><Select value={contract.billingCycle} onValueChange={value => setContract({ ...contract, billingCycle: value as typeof contract.billingCycle })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="monthly">Mensal</SelectItem><SelectItem value="quarterly">Trimestral</SelectItem><SelectItem value="annual">Anual</SelectItem></SelectContent></Select><Input type="number" min="0" step="0.01" placeholder="MRR" value={contract.mrr} onChange={e => setContract({ ...contract, mrr: e.target.value })} /><Button type="submit">Salvar contrato</Button></form></CardContent></Card><Card><CardHeader><CardTitle>Nova licença ativa</CardTitle></CardHeader><CardContent><form className="grid gap-4 md:grid-cols-3" onSubmit={e => { e.preventDefault(); if (!license.contractId || !license.licenseKey) return toast.error("Selecione o contrato e informe a chave"); createLicense.mutate({ contractId: Number(license.contractId), licenseKey: license.licenseKey, activeSeats: Number(license.activeSeats) }); }}><Select value={license.contractId} onValueChange={value => setLicense({ ...license, contractId: value })}><SelectTrigger><SelectValue placeholder="Contrato" /></SelectTrigger><SelectContent>{(operations.contracts ?? []).map(item => <SelectItem key={item.id} value={String(item.id)}>{item.code}</SelectItem>)}</SelectContent></Select><Input placeholder="Chave da licença" value={license.licenseKey} onChange={e => setLicense({ ...license, licenseKey: e.target.value })} /><Input type="number" min="1" placeholder="Licenças ativas" value={license.activeSeats} onChange={e => setLicense({ ...license, activeSeats: e.target.value })} /><Button type="submit">Salvar licença</Button></form><p className="mt-4 text-xs text-muted-foreground">{(operations.licenses ?? []).length} licença(s) cadastrada(s). O MRR do dashboard será calculado pelos contratos ativos.</p></CardContent></Card></div>;
}

function OperationsForm({ operations, onDone }: { operations: { customers: any[]; bankAccounts: any[] }; onDone: () => void }) {
  const createCustomer = trpc.finance.createCustomer.useMutation({ onSuccess: () => { toast.success("Cliente cadastrado"); onDone(); }, onError: error => toast.error(error.message) });
  const createBank = trpc.finance.createBankAccount.useMutation({ onSuccess: () => { toast.success("Conta bancária cadastrada"); onDone(); }, onError: error => toast.error(error.message) });
  const [customer, setCustomer] = useState({ legalName: "", document: "", email: "" });
  const [bank, setBank] = useState({ name: "", institution: "", openingBalance: "" });
  return <div className="grid gap-6 lg:grid-cols-2"><Card className="border-border/70 shadow-sm"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><UserPlus className="h-4 w-4 text-blue-600" />Cadastrar cliente</CardTitle></CardHeader><CardContent><form className="space-y-4" onSubmit={e => { e.preventDefault(); if (!customer.legalName) return toast.error("Informe a razão social"); createCustomer.mutate({ legalName: customer.legalName, document: customer.document || undefined, email: customer.email || undefined }); }}><div className="space-y-2"><Label>Razão social / nome</Label><Input value={customer.legalName} onChange={e => setCustomer({ ...customer, legalName: e.target.value })} /></div><div className="space-y-2"><Label>CNPJ ou documento</Label><Input value={customer.document} onChange={e => setCustomer({ ...customer, document: e.target.value })} /></div><div className="space-y-2"><Label>E-mail financeiro</Label><Input type="email" value={customer.email} onChange={e => setCustomer({ ...customer, email: e.target.value })} /></div><Button type="submit" disabled={createCustomer.isPending}>Salvar cliente</Button></form><p className="mt-5 text-xs text-muted-foreground">{operations.customers.length} cliente(s) cadastrado(s). Contratos e licenças serão vinculados a estes registros.</p></CardContent></Card><Card className="border-border/70 shadow-sm"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><Landmark className="h-4 w-4 text-amber-600" />Cadastrar conta bancária</CardTitle></CardHeader><CardContent><form className="space-y-4" onSubmit={e => { e.preventDefault(); if (!bank.name) return toast.error("Informe o nome da conta"); createBank.mutate({ name: bank.name, institution: bank.institution || undefined, openingBalance: Number(bank.openingBalance || 0) }); }}><div className="space-y-2"><Label>Nome da conta</Label><Input value={bank.name} onChange={e => setBank({ ...bank, name: e.target.value })} placeholder="Conta operacional" /></div><div className="space-y-2"><Label>Instituição</Label><Input value={bank.institution} onChange={e => setBank({ ...bank, institution: e.target.value })} /></div><div className="space-y-2"><Label>Saldo inicial real</Label><Input type="number" min="0" step="0.01" value={bank.openingBalance} onChange={e => setBank({ ...bank, openingBalance: e.target.value })} /></div><Button type="submit" disabled={createBank.isPending}>Salvar conta</Button></form><p className="mt-5 text-xs text-muted-foreground">{operations.bankAccounts.length} conta(s) cadastrada(s). O saldo inicial é usado no cálculo de caixa e runway.</p></CardContent></Card></div>;
}

function GoalForm({ catalog, year, onDone }: { catalog: { products: any[] }; year: number; onDone: () => void }) {
  const upsert = trpc.finance.upsertGoal.useMutation({ onSuccess: () => { toast.success("Meta salva"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ quarter: "Q1" as "Q1" | "Q2" | "Q3" | "Q4", productId: "", targetNewCustomers: "", targetMrr: "", notes: "" });
  return <Card className="border-border/70 shadow-sm"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><Target className="h-4 w-4 text-blue-600" />Definir meta trimestral</CardTitle></CardHeader><CardContent><form className="grid gap-4 md:grid-cols-2 lg:grid-cols-5" onSubmit={e => { e.preventDefault(); if (!form.targetNewCustomers || !form.targetMrr) { toast.error("Informe clientes e MRR da meta"); return; } upsert.mutate({ year, quarter: form.quarter, productId: form.productId ? Number(form.productId) : undefined, targetNewCustomers: Number(form.targetNewCustomers), targetMrr: Number(form.targetMrr), notes: form.notes || undefined }); }}><div className="space-y-2"><Label>Trimestre</Label><Select value={form.quarter} onValueChange={value => setForm({ ...form, quarter: value as typeof form.quarter })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Q1", "Q2", "Q3", "Q4"].map(q => <SelectItem key={q} value={q}>{q}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Produto</Label><Select value={form.productId || "group"} onValueChange={value => setForm({ ...form, productId: value === "group" ? "" : value })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="group">Grupo Elo</SelectItem>{catalog.products.map(product => <SelectItem key={product.id} value={String(product.id)}>{product.name}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Novos clientes</Label><Input type="number" min="0" value={form.targetNewCustomers} onChange={e => setForm({ ...form, targetNewCustomers: e.target.value })} /></div><div className="space-y-2"><Label>MRR alvo</Label><Input type="number" min="0" step="0.01" value={form.targetMrr} onChange={e => setForm({ ...form, targetMrr: e.target.value })} /></div><div className="flex items-end"><Button className="w-full" disabled={upsert.isPending} type="submit">Salvar meta</Button></div></form></CardContent></Card>;
}

export default function Home() { return <DashboardLayout><HomeContent /></DashboardLayout>; }
